def transforms(cells):
    pts=set(map(tuple,cells))
    res=[]
    cur=pts
    for rot in range(4):
        # rotate by rot*90 then maybe flip
        opts=[cur,[ (c,-r) for r,c in cur], [(r,-c) for r,c in cur],[(-c,-r) for r,c in cur]]
